jump __start  ; entry
jump mmio     ; mmio interupt
call 0        ; swi interupt
call 0        ; div0 interupt
call 0        ; unaligned load store
jump __sdivmul; unsuported opcode
call 0        ; iot


__sdivmul:
        push r0
        push r4
        push r5
        skip 1 ifne r3 0b1001
        jump __soft_umull   ; umull == smull
        skip 1 ifne r3 0b1010
        jump __soft_smulh
        skip 1 ifne r3 0b1011
        jump __soft_umull
        skip 1 ifne r3 0b1100
        jump __soft_umulh
        skip 1 ifne r3 0b1101
        jump __soft_div
        skip 1 ifne r3 0b1110
        jump __soft_mod
        call 0
        
__soft_mod:
        copy r0 r1
        copy r1 r2
        call __divise_alg
        copy r1 r0
        pop r5
        pop r4
        pop r0
        reti

__soft_div:
        copy r0 r1
        copy r1 r2
        call __divise_alg
        pop r5
        pop r4
        pop r0
        reti

; algo de division
; Args:
; R0 = Dividende
; R1 = Diviseur
; Return:
; R0 = reste
; R1 = Quotien
__divise_alg:
        copy r3 16
        lsr  r2 r0 16
        skip 2 ifuge r2 r1
        copy r3 0
        copy r2 r0
        ;skip here
        lsr  r4 r2 8
        skip 2 ifult r4 r1
        add  r3 r3 8
        copy r2 r4
        ;skip here
        lsr  r4 r2 4
        skip 2 ifult r4 r1
        add  r3 r3 4
        copy r2 r4
        ;skip here
        lsr  r4 r2 2
        skip 2 ifult r4 r1
        add  r3 r3 2
        copy r2 r4
        ;skip here
        lsr  r4 r2 1
        skip 1 ifult r4 r1
        add  r3 r3 1
        ;skip here
        ; a ce point, r3 contient le nombre de shift gauche qu'il faut faire sur le diviseur pour le caller "juste en dessous" du dividende. Aussi nombre d'étape de division -1
        lsl r2 r1 r3
        copy r1 0
        ; états des registres:
        ; r0: dividende
        ; r1: quotient
        ; r2: diviseur shifté
        ; r3: nombre de tour de boucle a faire
__divise_loop_start:
        skip 1 ifge r3 0
        ret
        
        lsl r1 r1 1
        skipto __divise_loop_mid ifult r0 r2
        or r1 r1 1
        sub r0 r0 r2
__divise_loop_mid:
        lsr r2 r2 1
        sub r3 r3 1
        jump __divise_loop_start


__soft_umull:
        copy r0 r2
        call __umull_alg
        copy r1 r2
        pop r5
        pop r4
        pop r0
        reti

__soft_umulh:
        push r6 ;reserve registers
        push r7
        push r8

        call __long_mul

        pop r8 ; cleanup and return
        pop r7
        pop r6
        pop r5
        pop r4
        pop r0
        reti

__soft_smulh:
        push r6
        push r7
        push r8
        push r9
        
        copy r9 0
        let r6 0x80000000
        and r5 r1 r6
        skip 1 ifeq r5 0
        copy r9 r2
        
        and r4 r2 r6
        skip 1 ifeq r4 0
        add r9 r9 r1

        call __long_mul

        sub r1 r1 r9

        pop r9
        pop r8
        pop r7
        pop r6
        pop r5
        pop r4
        pop r0
        reti
        

        

__long_mul:
        ;prepare halfs to mult
        and r4 r1 0xFFFF ; r1 low half
        lsr r5 r1 16     ; r1 upper half
        and r6 r2 0xFFFF ; r2 low half
        lsr r7 r2 16     ; r2 upper half

        copy r0 r5
        copy r1 r7
        call __umull_alg
        copy r8 r2       ; main high*high result
        
        copy r0 r7       ; preffer upper half (more chance of being little) for faster mul
        copy r1 r4
        call __umull_alg
        and r7 r2 0xFFFF ; lower half for carry. r7 reused
        lsr r2 r2 16     ; upper half of low * high, added to final result.
        add r8 r8 r2

        copy r0 r5
        copy r1 r6
        call __umull_alg
        lsr r1 r2 16     ; upper half, add to main result
        add r8 r8 r1     
        and r2 r2 0xFFFF ; low half, carry
        add r7 r7 r2

        copy r0 r4
        copy r1 r6
        call __umull_alg
        lsr r1 r2 16    ;upper half of low * low, add to carry
        add r7 r7 r1
        lsr r6 r7 16    ;upper half of carry, add to main for result
        add r1 r6 r8

        
        ;r1: main result
        ;r8: result without carry
        ;r7: carry
        ;r6: shifted carry
        ;r2: low*low
        ret

        
        

; r0 * r1
; result in r2
; use registers r0-3
__umull_alg:
        copy r2 0
__umull_alg_loop:
        skipto 1 ifne r0 0
        ret
        ;skip here
        and r3 r0 1
        skip 1 ifeq r3 0
        add r2 r2 r1
        lsr r0 r0 1
        lsl r1 r1 1
        jump __umull_alg_loop


;point d'entrée
__start:
        let r0 0x01000000
        copy SP r0 ; setup stack pointer
        eint
main:
        let r0 0x01201000
        let r1 14
        store [r0] r1

        let r15 store_game_vars
        let r14 0x01200004 ; horloge
        let r13 store_plantes
        let r12 store_plantes_data
        let r11 store_zombie_data
        
        ;halt
main_game_logic_loop:
        load r10 [r14] ; clock actual

        load r9 [r15+16] ; soleil natural gen
        skipto main_loop2 ifugt r9 r10
                add r9 r9 6000
                store [r15+16] r9
                load r9 [r15]  ;no mutex on that ... we consider the bug if interrupt for clic happen here to be rare enough to be ok
                add r9 r9 25
                store [r15] r9
                
        main_loop2:
        
        copy r9 0 ; store_add
        copy r8 0 ;x
        copy r7 0 ;y
        main_loop_plant_loop:
                skip 2 iflt r8 9
                        add r7 r7 1
                        copy r8 0
                skip 1 iflt r7 5
                        jump main_loop3
                
                add r6 r9 r13
                load r4 [r6] ;id
                skipto main_loop_plant_loop_continue ifeq r4 -1
                load r5 [r6+8]
                skipto main_loop_plant_loop_continue ifugt r5 r10
                umull r4 r4 24
                add r4 r4 r12
                load r2 [r4+8]
                load r3 [r4+12]
                add r5 r5 r3
                store [r6+8] r5
                copy r0 r8
                copy r1 r7
                call call_by_ptr
                
                         
        main_loop_plant_loop_continue:
                add r8 r8 1
                add r9 r9 12 ; 3 word each
                jump main_loop_plant_loop

        main_loop3:


        push r13 ; we need a bit more room
        
        let r9 store_zombies
        let r8 0 ; x in store
        let r7 0 ; y

        main_loop_zombie_loop:
        skip 2 iflt r8 20
                copy r8 0
                add r7 r7 1
        skip 1 iflt r7 5
                jump main_loop4
        load r6 [r9]
        skip 2 ifeq r6 -1
          load r13 [r9+16]
          skip 1 ifle r13 r10
                jump main_loop_zombie_continue
        umull r6 r6 20
        add r6 r6 r11
        load r4 [r9+12]
        skipto main_loop_zombie_advance ifugt r4 40

        load r0 [r6+8]
        load r1 [r9+8]
        copy r2 r7
        call damage_plante
        skipto main_loop_zombie_advance_pre ifeq r0 0
        load r0 [r6+12]
        add r13 r13 r0
        store [r9+16] r13
        jump main_loop_zombie_continue

        main_loop_zombie_advance_pre:
        load r4 [r9+12]
        main_loop_zombie_advance: ; assume r4 is current x in case
                                  ; assume r13 is current time
        load r5 [r6+16]
        add r13 r13 r5
        store [r9+16] r13
        skipto main_loop_zombie_change_case ifle r4 0
        sub r4 r4 1
        store [r9+12] r4
        
        main_loop_zombie_continue:
        add r8 r8 1
        add r9 r9 20
        jump main_loop_zombie_loop

        main_loop_zombie_change_case:
        add r4 r4 64
        load r5 [r9+8]
        sub r5 r5 1
        skip 1 ifge r5 0
                jump game_lost
        store [r9+12] r4
        store [r9+8] r5
        

        jump main_loop_zombie_continue
        
        
        main_loop4:

        ; update pseudo random
        load r9 [r15+24]
        let r0 2690201
        umull r9 r9 r0
        xor r9 r10 r9
        store [r15+24] r9

        load r8 [r15+28]
        load r6 [r8]
        skip 1 ifuge r10 r6
                jump main_loop5
        
        load r7 [r15+32]
        and r9 r9 3
        add r7 r7 r9
        add r7 r7 1 ;a different line from previous spawn, randomized
        mod r7 r7 5

        load r6 [r8+4] ; spread
        copy r9 0
        add r8 r8 8

        main_loop_spawn_loop:
                load r13 [r8]

                main_loop_spawn_inner:
                skipto main_loop_spawn_break ifle r13 0
                        copy r0 r7
                        copy r1 r9
                        call create_zombie
                        add r7 r7 r6
                        skip 1 iflt r7 5
                                sub r7 r7 5
                        sub r13 r13 1
                        jump main_loop_spawn_inner
                main_loop_spawn_break:
                
                add r9 r9 1
                add r8 r8 4
                skip 1 ifeq r9 3
                jump main_loop_spawn_loop

        store [r15+28] r8
        store [r15+32] r7
        
        
        main_loop5:

        let r13 store_pois
        push r11
        let r11 store_zombies
        let r9 0 ; line
        let r8 0 ; counter in line

        main_loop_pois:


        load r0 [r13]
        skip 1 ifne r0 -1
                jump main_loop_pois_continue
        load r2 [r13+8]
        skip 1 ifge r10 r2
                jump main_loop_pois_continue
        add r2 r2 10
        store [r13+8] r2
        load r1 [r13+4]

        add r1 r1 3
        skip 6 ifle r1 64
                sub r1 r1 65
                add r0 r0 1
                skip 3 iflt r0 9
                copy r0 -1
                store [r13] r0
                jump main_loop_pois_continue
                
        store [r13+4] r1
        store [r13] r0 ; may not have changed but i do not care

        ; scan zombie to find a nearby one
        let r7 0 ; counter
        copy r6 r11



        loop_pois_find_zombie:
                load r2 [r6]
                skipto loop_pois_find_continue ifeq r2 -1
                load r2 [r6+8]
                load r3 [r6+12]

                skipto loop_pois_find_continue ifgt r2 r0
                skip 2 ifeq r0 r2
                        sub r2 r2 1
                        add r3 r3 65
                skipto loop_pois_find_continue iflt r0 r2
                add r3 r3 3
                skipto loop_pois_find_continue iflt r3 r1
                sub r3 r3 6
                skipto loop_pois_find_continue ifgt r3 r1
                jump loop_pois_found_zombie
                                
        loop_pois_find_continue:
                add r7 r7 1
                add r6 r6 20
                skipto main_loop_pois_continue ifge r7 20
        jump loop_pois_find_zombie

        
        loop_pois_found_zombie:
        ; r6 is the zombie ptr
        test_label:
        copy r5 -1
        store [r13] r5 ; destroy the pois
        load r4 [r6+4]
        sub r4 r4 10
        store [r6+4] r4
        skip 1 ifgt r4 0
                store [r6] r5

        
        main_loop_pois_continue:
        add r8 r8 1
        add r13 r13 12
        skip 4 iflt r8 20
                copy r8 0
                add r9 r9 1
                add r11 r11 400
                skip 1 ifge r9 5
        jump main_loop_pois
        




        main_loop6:
        pop r11
        pop r13

jump main_game_logic_loop



; stores
; game_vars:
;    - nb_soleil
;    - plante selectionné
;    - selection x
;    - selection y
; plantes: 8*6,
;     - plante ID
;     - Vie
;     - next_action
; plantes_data: for each plant by id
;     - sprite ptr
;     - prix
;     - ptr de fonction on fire: args pos x y en case de la plante
;     - fréquence (nb de milliseconde entre chaque attaque)
;     - pv
;     - ptr de fonction on death: args pos x y en case de la plante
; zombie_data
;     - sprite ptr
;     - vie
;     - dégats
;     - freq_atq
;     - speed (en ms/pix)


;r0: //legacy, ignored
;r1: plante_id
;r2: horizontal square
;r3: vertical square
;
;Return:

display_big_plante:
        
        let r4 store_plantes_data
        umull r1 r1 24 ; 4*6
        add r4 r1 r4
        
        umull r2 r2 65
        umull r3 r3 77
        add r1 r2 30 ; plant drawing area
        add r2 r3 68 ; plant drawing area

        load r3 [r4]
        
        jump print_pict


; r0: plante_id
; r1: x
; r2: y
create_plante:
        push r6
        
        let r3 store_plantes_data
        umull r4 r0 24 ;4bytes * 6champs dans plantes_data
        add r3 r3 r4

        umull r2 r2 9
        add r1 r1 r2
        umull r1 r1 12

        ; handle price, exit if too costy
        let r5 store_game_vars
        load r2 [r5]   ;soleils dispo
        load r4 [r3+4] ;prix
        skip 1 ifge r2 r4
                jump create_plante_end
        sub r2 r2 r4
        store [r5] r2

        
        let r4 store_plantes
        add r4 r1 r4

        store [r4] r0
        load r5 [r3+16]
        store [r4+4] r5

        let r5 24000
        skip 1 ifeq r0 0 ; special case for tournesol due to animation making it the wrong timer
                load r5 [r3+12]
        let r3 0x01200004 ; horloge
        load r3 [r3]
        add r0 r5 r3
        store [r4+8] r0

create_plante_end:
        pop r6
        ret

; args: r0: dégats
;       r1: x
;       r2: y
; Return: 0 si pas de plante
;         1 si plante présente (et endomagée)
damage_plante:
        let r4 store_plantes
        umull r3 r2 9
        add r3 r3 r1
        umull r3 r3 12
        add r3 r3 r4
        load r4 [r3]
        skip 2 ifne r4 -1
                copy r0 0
                ret
        load r5 [r3+4]
        sub r5 r5 r0
        store [r3+4] r5
        skipto damage_plante_end ifgt r5 0
        copy r5 -1
        store [r3] r5
        copy r0 r1
        copy r1 r2
        let r2 store_plantes_data
        umull r4 r4 24
        add r2 r2 r4
        load r2 [r2+20] ; on death
        call call_by_ptr

damage_plante_end:
        copy r0 1
        ret
                


game_lost:
        let r0 0x01201000
        let r1 1
        store [r0] r1
        let r1 0
        let r2 0
        let r3 picture_game_over
        call print_pict
        halt


;Args: R0 ligne
;Args: R1 Type
create_zombie:
        let r2 store_zombies
        umull r0 r0 400
        add r0 r0 r2
create_zombie_slot_finder:
        load r2 [r0]
        skip 2 ifeq r2 -1
                add r0 r0 40
                jump create_zombie_slot_finder
        

        let r3 8
        store [r0+8] r3
        let r3 64
        store [r0+12] r3
        let r3 0x01200004
        load r3 [r3]
        store [r0+16] r3
        store [r0] r1
        let r3 store_zombie_data
        umull r1 r1 20
        add r1 r1 r3
        load r3 [r3+4]
        store [r0+4] r3
        ret

mmio:
        skip 1 ifne r0 2
                jump mmio_mouse_move
        skip 1 ifne r0 1
                jump mmio_mouse_clic
        skip 1 ifne r0 3
                jump mmio_frame_display
        call 0

mmio_mouse_move:
        push r1
        push r2
        let r1 0x0120000c ; MMIO mouse pos
        load r0 [r1]
        load r1 [r1+4]
        skipto mmio_mouse_move_illegal iflt r0 30
        skipto mmio_mouse_move_illegal iflt r1 68
        sub r0 r0 30
        sub r1 r1 68
        div r0 r0 65
        div r1 r1 77
        skipto mmio_mouse_move_illegal ifge r0 9
        skipto mmio_mouse_move_illegal ifge r1 5

mmio_mouse_move_end:
        let r2 store_game_vars
        store [r2+8] r0
        store [r2+12] r1        

        pop r2
        pop r1
        reti
mmio_mouse_move_illegal:
        copy r0 -1
        copy r1 -1
        jump mmio_mouse_move_end    


mmio_mouse_clic:
        push r5
        let r5 0x01200008 ;mmio souris 
        load r0 [r5]
        skip 2 ifeq r0 1 ;clic gauche
                pop r1
                reti
        
        push r2
        push r3
        push r4
        push r1

        let r3 store_game_vars
        load r0 [r3+4]
        load r1 [r3+8]
        load r2 [r3+12]
        skipto mouse_clic_store ifeq r0 -1
        skipto mouse_clic_store ifeq r1 -1
        skipto mouse_clic_store ifeq r2 -1
        copy r4 -1
        store [r3+4] r4
        call create_plante
        jump mouse_clic_end

mouse_clic_store:
        load r1 [r5+4]
        load r0 [r5+8]
        call quelle_plante
        store [r3+4] r0 ; pas beaux, mais en pratique r3 non écrasé par quelle_plante

mouse_clic_end:
        pop r1
        pop r4
        pop r3
        pop r2
        pop r5
        reti


mmio_frame_display:
        push r1
        
        ;30 fps frame limiter
        let r1 store_game_vars
        load r0 [r1+20]
        skip 4 ifeq r0 1
                copy r0 1
                store [r1+20] r0
                pop r1
                reti
        copy r0 0
        store [r1+20] r0
        
        push r2
        push r3
        push r4
        push r5
        push r6
        push r7
        push r8
        push r9
        push r10
        
        call print_background

        ; -------
        ; print plants
        ; -------
        
        let r7 0
        let r8 0
        let r6 store_plantes
        let r9 store_game_vars
display_all_plants_loop:
        load r1 [r6]
        skipto display_all_plants_plant ifne r1 -1
        
        load r3 [r9+8]
        skipto display_all_plants_loop_end ifne r3 r7
        load r3 [r9+12]
        skipto display_all_plants_loop_end ifne r3 r8
        ;plant selected for placement and on this block
        load r1 [r9+4]
        skipto display_all_plants_loop_end ifeq r1 -1
        
        display_all_plants_plant:
                copy r3 r8
                copy r2 r7
                call display_big_plante

display_all_plants_loop_end:
        add r7 r7 1
        add r6 r6 12
        skip 3 iflt r7 9
                copy r7 0
                add r8 r8 1
        skip 1 ifeq r8 5
                jump display_all_plants_loop
        ; ------
        ; sun counter
        ; ------
        let r0 0xFF ; black
        load r1 [r9]
        let r2 45
        let r3 46
        call print_int

        ; -----
        ; zombies
        ; -----

        let r9 store_zombies
        let r8 store_zombie_data
        let r7 0 ; index in z array
        let r6 0 ; line in z array
        let r10 65; initial y value

display_zombie_loop:
        load r5 [r9]
        skipto display_zombie_loop_continue ifeq r5 -1
        umull r5 r5 20
        load r3 [r5+r8]

        load r5 [r9+8]
        load r4 [r9+12]
        umull r5 r5 65
        add r1 r5 r4
        add r1 r1 10

        copy r2 r10
        call print_pict

display_zombie_loop_continue:
        add r9 r9 20
        add r7 r7 1
        skip 3 iflt r7 20
                copy r7 0
                add r6 r6 1
                add r10 r10 77
        skip 1 ifeq r6 5
                jump display_zombie_loop



        ; -----
        ; pois
        ; -----

        let r10 picture_pois
        let r9 store_pois
        let r8 0 ; counter in line
        let r7 0 ; line
        let r6 75;

display_pois_loop:
        load r0 [r9]
        skipto display_pois_continue ifeq r0 -1
        umull r0 r0 65
        add r0 r0 23
        load r1 [r9+4]
        add r1 r1 r0
        copy r2 r6
        copy r3 r10
        call print_pict

        display_pois_continue:
        add r9 r9 12
        add r8 r8 1
        skip 4 iflt r8 20
                add r7 r7 1
                copy r8 0
                add r6 r6 77
        
                skip 1 ifeq r7 5
        jump display_pois_loop

        pop r10
        pop r9
        pop r8
        pop r7
        pop r6
        pop r5
        pop r4
        pop r3
        pop r2
        pop r1
        
        reti





; Args: r0: y
; Args r1   x
; return: r0: indice plante ou -1 si pas sur une plante
quelle_plante :
	skip 1 ifne r0 -1	;hors de l'écran
	jump pas_plante		
	skip 1 ifne r1 -1	;hors de l'écran
	jump pas_plante
	skip 1 ifle r0 43	;trop bas
	jump pas_plante
	skip 1 ifge r0 4	;trop haut
	jump pas_plante
	skip 1 ifge r1 75	;trop à gauche
	jump pas_plante
	skip 1 ifle r1 348	;trop à droite
	jump pas_plante
	skip 2 ifgt r1 113	;si trop à droite pour être le tournesol
	copy r0 0
	jump quelle_plante_fin
	skip 1 ifge r1 122	;entre tournesol et pisto-pois
	jump pas_plante
	skip 2 ifgt r1 159	;pisto-pois ? 
	copy r0 1
	jump quelle_plante_fin	
	skip 1 ifge r1 171	;entre pistopois et cerise
	jump pas_plante
	skip 2 ifgt r1 208 	;cerise ? 
	copy r0 2
	jump quelle_plante_fin	
	skip 1 ifge r1 218	;entre cerise et double pistopois
	jump pas_plante
	skip 2 ifgt r1 255	;double pistopois ? 
	copy r0 3
	jump quelle_plante_fin
	skip 1 ifge r1 266	;entre double pistopois et noix
	jump pas_plante
	skip 2 ifgt r1 300	;noix  ? 
	copy r0 4
	jump quelle_plante_fin
	skip 1 ifge r1 312	;entre noix et mine 
	jump pas_plante
	skip 2 ifgt r1 348	;mine ? 
	copy r0 5
	jump quelle_plante_fin
	jump pas_plante


	
pas_plante :
	copy r0 -1

quelle_plante_fin :
	ret
; Args: R0: Couleur
;       R1,R2 coordonées en haut a gauche
;       R3,R4 coordonées en bas a droite
; Retourne: R0: Couleur
rectfill:
        umull r2 r2 2560
        let r5 0x01000000
        add r2 r2 r5
        umull r4 r4 2560
        add r4 r4 r5
        lsl r1 r1 2
        lsl r3 r3 2
        copy r5 r1
rectfill_outer_loop:
        copy r1 r5

rectfill_inner_loop:
        store [r1+r2] r0
        add r1 r1 4
        skip 1 ifgt r1 r3
        jump rectfill_inner_loop
        
        add r2 r2 2560
        skip 1 ifle r2 r4
        ret
        jump rectfill_outer_loop
        

; Args: R0: couleur de remplisssage
; Return: R0 Couleur, r3-r5: non modifiés
screen_clr:
        let r1 0x01000000
        let r2 0x0112C000
screen_clr_loop:
        store [r1] r0
        add r1 r1 4
        skip 1 ifge r1 r2
        jump screen_clr_loop
        ret

print_background:
        let r1 0
        let r2 0
        let r3 picture_background
        jump print_pict


; Args: R0: Couleur
;       R1 buffer
;       R2,R3 coordonées du point
; Return R0: Couleur R4-R5 non modifiés
plot:
        umull r3 r3 640
        add r2 r2 r3
        lsl r2 r2 2
        store [r1+r2] r0
        ret

;Args: R0 //Anything, ignored
;R1,R2 coordonées du coin haut gauche
;R3: Pointeur sur l'image

print_pict:
        push r6
        
        let r0 0x01000000
        load r4 [r3]     ;width
        load r5 [r3+4]   ;height
        add r3 r3 8      ;data start

        umull r2 r2 640 ;*640*4
        add r1 r1 r2
        lsl r1 r1 2      ;*4
        add r1 r1 r0     ; r1 = memory start
        
        copy r2 r4    ;set column counter
print_pict_w_loop:
        skipto print_pict_w_loop_2 ifne r2 0
                let r2 640
                sub r2 r2 r4
                lsl r2 r2 2
                add r1 r1 r2  ;next line
                sub r5 r5 1   ;decrease line conter
                skipto print_pict_end ifeq r5 0
                copy r2 r4
                jump print_pict_w_loop
print_pict_end:
        pop r6
        ret
                
        print_pict_w_loop_2:
                skipto print_pict_rolled iflt r2 5
                ; slight loop unrolling for perfomance because we abuse of this function in rendering
                load r6 [r3]
                skip 1 ifeq r6 0
                        store [r1] r6
                load r6 [r3+4]
                skip 1 ifeq r6 0
                        store [r1+4] r6
                load r6 [r3+8]
                skip 1 ifeq r6 0
                        store [r1+8] r6
                load r6 [r3+12]
                skip 1 ifeq r6 0
                        store [r1+12] r6
                add r3 r3 16
                add r1 r1 16
                sub r2 r2 4

        print_pict_rolled:
                load r6 [r3]
                add r3 r3 4
                skip 1 ifeq r6 0
                        store [r1] r6
                add r1 r1 4
                sub r2 r2 1
                jump print_pict_w_loop    

                


;R0 = couleur
;R1 = buffer; ignoré
;R2,R3 = Coordonées en haut a gauche
;R4 = ascii du char
; renvoie R0 = couleur
print_char:
        skip 1 ifult r4 256        
        ret
print_char_unsafe: ;must be certain that code < 256
        push r6
        let r5 picture_fontplate
        lsl r4 r4 4  ; 8*16 bit per char => 16 byte per char
        add r4 r4 r5
        umull r3 r3 640
        add r2 r2 r3
        lsl r2 r2 2
        let r1 0x01000000
        add r2 r1 r2

        
        let r5 128
        load r3 [r4]
        
print_char_loop:
        and r6 r3 1
        skip 1 ifne r6 1
                store [r2] r0

        lsr r3 r3 1
        sub r5 r5 1
        skipto print_char_end ifeq r5 0
        and r6 r5 7
        skip 1 ifne r6 0
                add r2 r2 2528
        and r6 r5 31
        skip 2 ifne r6 0
                load r3 [r4+4]
                add r4 r4 4
        add r2 r2 4
        jump print_char_loop        
        
        
print_char_end:
        pop r6
        ret

;r0 couleur
;r1 valeur
;r2 x
;r3 y
print_int:
push r6
push r7
push r8

        div r6 r1 10
        mod r4 r1 10
        copy r7 r2
        copy r8 r3
        add r4 r4 48
        call print_char_unsafe
        print_int_loop:
                skipto print_int_end ifeq r6 0
                mod r4 r6 10
                div r6 r6 10
                add r4 r4 48
                sub r7 r7 8
                copy r2 r7
                copy r3 r8
                call print_char_unsafe
        jump print_int_loop
        
print_int_end:
pop r8
pop r7
pop r6
ret

